67         owner = msg.sender;
68     }
69 
70     // ---------------------------------------------------------------------
71     // External functions
72     // ---------------------------------------------------------------------
73 
74     /**
75      * @notice Lock ETH until `unlockTime` (unix timestamp).
76      * @param unlockTime Must be greater than current block.timestamp.
77      * @return depositId The id (index) of the new deposit for the caller.
78      */
79     function deposit(uint256 unlockTime) external payable returns (uint256 depositId) {
80         require(msg.value > 0, "Must send ETH");
81         require(unlockTime > block.timestamp, "Unlock time must be in the future");
82 
83         deposits[msg.sender].push(
84             Deposit({
85                 amount: msg.value,
86                 unlockTime: unlockTime,
87                 withdrawn: false
88             })
89         );
90 
91         depositId = deposits[msg.sender].length - 1;
92 
93         lockedBalance[msg.sender] += msg.value;
94         totalLocked += msg.value;
95 
96         emit Deposited(msg.sender, depositId, msg.value, unlockTime);
97     }
98 
99     /**
100      * @notice Withdraw a specific deposit after its unlock time.
101      * @param depositId The id of the deposit to withdraw.
102      */
103     function withdraw(uint256 depositId) external {
104         require(depositId < deposits[msg.sender].length, "Invalid deposit id");
105 
106         Deposit storage d = deposits[msg.sender][depositId];
107         require(!d.withdrawn, "Already withdrawn");
108         require(block.timestamp >= d.unlockTime, "Still locked");
109 
110         uint256 amount = d.amount;
111         d.withdrawn = true;
112 
113         lockedBalance[msg.sender] -= amount;
114         totalLocked -= amount;
115 
116         (bool ok, ) = payable(msg.sender).call{value: amount}("");
117         require(ok, "ETH transfer failed");
118 
119         emit Withdrawn(msg.sender, depositId, amount);
120     }
121 
122     /**
123      * @notice Convenience: withdraw all deposits that are currently unlocked.
124      */
125     function withdrawAllUnlocked() external {
126         Deposit[] storage userDeposits = deposits[msg.sender];
127         uint256 totalAmount = 0;
128 
129         for (uint256 i = 0; i < userDeposits.length; i++) {
130             Deposit storage d = userDeposits[i];
131             if (!d.withdrawn && block.timestamp >= d.unlockTime) {
132                 totalAmount += d.amount;
133                 d.withdrawn = true;
134                 emit Withdrawn(msg.sender, i, d.amount);
135             }
136         }
137 
138         require(totalAmount > 0, "Nothing to withdraw");
139 
140         lockedBalance[msg.sender] -= totalAmount;
141         totalLocked -= totalAmount;
142 
143         (bool ok, ) = payable(msg.sender).call{value: totalAmount}("");
144         require(ok, "ETH transfer failed");
145     }
146 
147     /**
148      * @notice Emergency: owner can withdraw the entire contract balance.
149      * @dev Should only be used if something is seriously wrong.
150      */
151     function emergencyWithdraw() external onlyOwner {
152         uint256 balance = address(this).balance;
153         require(balance > 0, "No balance");
154 
155         totalLocked = 0;
156 
157         (bool ok, ) = payable(owner).call{value: balance}("");
158         require(ok, "ETH transfer failed");
159 
160         emit EmergencyWithdrawn(owner, balance);
161     }
162 
163     /**
