8  *         The owner has an emergency withdrawal function to rescue funds.
9  */
10 contract TimeLockSavings {
11     // ---------------------------------------------------------------------
12     // Types
13     // ---------------------------------------------------------------------
14 
15     struct Deposit {
16         uint256 amount;       // amount of ETH locked (in wei)
17         uint256 unlockTime;   // unix timestamp when funds become withdrawable
18         bool withdrawn;       // whether this deposit has already been withdrawn
19     }
20 
21     // ---------------------------------------------------------------------
22     // State
23     // ---------------------------------------------------------------------
24 
25     address public owner;
26 
27     /// @notice Each user can have multiple deposits (like different "buckets").
28     mapping(address => Deposit[]) private deposits;
29 
30     /// @notice Total amount each user has locked (only counting active deposits).
31     mapping(address => uint256) public lockedBalance;
32 
33     /// @notice Total ETH held by the contract (for quick emergency accounting).
34     uint256 public totalLocked;
35 
36     // ---------------------------------------------------------------------
37     // Events
38     // ---------------------------------------------------------------------
39 
40     event Deposited(
41         address indexed user,
42         uint256 indexed depositId,
43         uint256 amount,
44         uint256 unlockTime
45     );
46     event Withdrawn(
47         address indexed user,
48         uint256 indexed depositId,
49         uint256 amount
50     );
51     event EmergencyWithdrawn(address indexed owner, uint256 amount);
52 
53     // ---------------------------------------------------------------------
54     // Modifiers
55     // ---------------------------------------------------------------------
56 
